-- SOCCER LAB: the whole database for a NEW, EMPTY Supabase project, in one file.
-- Made by make-setup.py from the dated files in this folder. Do not edit this file; edit those and run it again.
-- How: Supabase dashboard > SQL Editor > New query > paste all of this > Run. Run it ONCE.
-- It runs as one transaction: if anything fails, nothing is kept and it can be run again after the fix.

begin;

-- ====================================================================================================
-- FILE: 2026-10-25-base.sql
-- ====================================================================================================

-- BASE TABLES for a NEW Supabase project (written 2026-11-12).
-- The other files in this folder are changes made on top of the first Supabase project, whose original setup was
-- never saved as a file. This file rebuilds that starting point from what the app sends and reads (Data/Team.swift)
-- and from what the later files expect to find (table, rule and constraint names they change or drop), so that on an
-- empty project every file runs without edits, this one first and 2026-11-13-new-project-finish.sql last.
-- The exact order is in make-setup.py, which joins them all into  setup-new-project.sql : paste that ONE file into
-- the new project's SQL editor instead of running these one by one. Run it ONCE; it is not meant to be re-run.

create schema if not exists private;
-- rules below call private.* functions as the signed-in player, so the role needs to reach the schema (tables in it
-- are never granted)
grant usage on schema private to authenticated;

-- ---------------------------------------------------------------------------------------------------------------
-- profiles: one row per signed-in player (what teammates see: name, position, streak, minutes, a tiny picture)
-- ---------------------------------------------------------------------------------------------------------------
create table public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  name text check (name is null or length(name) <= 40),
  "position" text check ("position" is null or length("position") <= 40),
  streak integer not null default 0 check (streak between 0 and 100000),
  week_minutes integer not null default 0 check (week_minutes between 0 and 20000),
  week_start date,
  last_active timestamptz,
  club text check (club is null or length(club) <= 60),
  level integer check (level is null or level between 0 and 999),
  avatar text check (avatar is null or length(avatar) < 40000),      -- a small JPEG as base64
  avatar_v integer,
  trial_until timestamptz,                                           -- set only by the join / gift / code functions
  trial_used boolean not null default false,
  created_at timestamptz not null default now()
);
alter table public.profiles enable row level security;

-- teams
create table public.teams (
  id uuid primary key default gen_random_uuid(),
  name text not null check (length(trim(name)) between 1 and 40),
  logo text check (logo is null or length(logo) < 20000),            -- a 128 px JPEG as base64
  color integer not null default 0 check (color between 0 and 31),
  code text not null unique check (code ~ '^[A-Z2-9]{6}$'),          -- 2026-10-28 swaps this for 6 digits
  owner uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now()
);
alter table public.teams enable row level security;

-- who is on which team (2026-10-27 changes the key so a player can be on many)
create table public.team_members (
  user_id uuid not null references public.profiles (id) on delete cascade,
  team_id uuid not null references public.teams (id) on delete cascade,
  joined_at timestamptz not null default now(),
  constraint team_members_pkey primary key (user_id)
);
create index team_members_team_idx on public.team_members (team_id);
alter table public.team_members enable row level security;

-- the team feed: chat + activity. Text only.
create table public.feed (
  id bigint generated always as identity primary key,
  team_id uuid not null references public.teams (id) on delete cascade,
  user_id uuid not null references public.profiles (id) on delete cascade,
  kind text not null check (length(kind) <= 20),
  body text check (body is null or length(body) <= 500),
  ref text check (ref is null or length(ref) <= 80),
  meta jsonb check (meta is null or pg_column_size(meta) < 20000),
  created_at timestamptz not null default now()
);
create index feed_team_idx on public.feed (team_id, id desc);
create index feed_user_recent_idx on public.feed (user_id, created_at desc);
alter table public.feed enable row level security;

-- ---------------------------------------------------------------------------------------------------------------
-- what the app's signed-in role may touch. Nothing for signed-out visitors. Columns that carry access
-- (trial_until, trial_used, later free_for_life) and a team's code / owner are readable but never writable from the
-- app: only the functions change them.
-- ---------------------------------------------------------------------------------------------------------------
revoke all on public.profiles, public.teams, public.team_members, public.feed from anon, authenticated;

grant select on public.profiles to authenticated;
grant insert (id, name, "position", streak, week_minutes, week_start, last_active, club, level, avatar, avatar_v),
      update (name, "position", streak, week_minutes, week_start, last_active, club, level, avatar, avatar_v)
  on public.profiles to authenticated;

grant select on public.teams to authenticated;
grant update (name, logo, color) on public.teams to authenticated;

grant select on public.team_members to authenticated;

grant select, delete on public.feed to authenticated;
grant insert (team_id, user_id, kind, body, ref, meta) on public.feed to authenticated;

-- ---------------------------------------------------------------------------------------------------------------
-- helpers
-- ---------------------------------------------------------------------------------------------------------------

-- my team (one team per player at first; 2026-10-27 replaces this with private.my_teams())
create function private.my_team() returns uuid
  language sql stable security definer set search_path = '' as $$
  select team_id from public.team_members where user_id = (select auth.uid())
$$;

-- a team code nobody has yet
create function private.new_code() returns text
  language plpgsql set search_path = '' as $$
declare c text; abc text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
begin
  loop
    c := '';
    for i in 1..6 loop c := c || substr(abc, 1 + floor(random() * length(abc))::int, 1); end loop;
    exit when not exists (select 1 from public.teams where code = c);
  end loop;
  return c;
end $$;

-- spam guard on the feed (2026-10-27 makes it per team)
create function private.feed_rate_limit() returns trigger
  language plpgsql security definer set search_path = '' as $$
begin
  if (select count(*) from public.feed where user_id = new.user_id and created_at > now() - interval '1 minute') >= 8 then
    raise exception 'slow down' using errcode = 'P0001';
  end if;
  return new;
end $$;
create trigger feed_rate_limit before insert on public.feed
  for each row execute function private.feed_rate_limit();

-- ---------------------------------------------------------------------------------------------------------------
-- rules (Row Level Security)
-- ---------------------------------------------------------------------------------------------------------------

create policy "see self and teammates" on public.profiles for select using (
  id = (select auth.uid()) or id in (select m.user_id from public.team_members m where m.team_id = (select private.my_team())));
create policy "make own profile" on public.profiles for insert to authenticated with check (id = (select auth.uid()));
create policy "edit own profile" on public.profiles for update to authenticated
  using (id = (select auth.uid())) with check (id = (select auth.uid()));

create policy "see my team" on public.teams for select using (id = (select private.my_team()));
create policy "owner edits team" on public.teams for update
  using (id = (select private.my_team()) and owner = (select auth.uid()))
  with check (id = (select private.my_team()) and owner = (select auth.uid()));

create policy "see teammates" on public.team_members for select using (team_id = (select private.my_team()));

create policy "read team feed" on public.feed for select using (team_id = (select private.my_team()));
create policy "post to team feed" on public.feed for insert with check (
  team_id = (select private.my_team()) and user_id = (select auth.uid())
  and kind = any (array['chat','session','film','share_session','share_film']));
create policy "delete own posts" on public.feed for delete to authenticated using (user_id = (select auth.uid()));

-- ---------------------------------------------------------------------------------------------------------------
-- functions the app calls (create_team / join_team / leave_team(uuid) arrive with 2026-10-27-multi-teams.sql)
-- ---------------------------------------------------------------------------------------------------------------

-- what a team code opens, before joining: name, crest, colour, size. Signed-in players only.
create function public.team_preview(p_code text)
  returns table (name text, logo text, color integer, members integer)
  language sql stable security definer set search_path = '' as $$
  select t.name, t.logo, t.color, (select count(*)::int from public.team_members m where m.team_id = t.id)
  from public.teams t
  where t.code = upper(trim(p_code)) and (select auth.uid()) is not null
$$;
revoke all on function public.team_preview(text) from public, anon;
grant execute on function public.team_preview(text) to authenticated;

-- the first app version's "leave my team" (2026-10-27 drops it for leave_team(uuid))
create function public.leave_team() returns void
  language plpgsql security definer set search_path = '' as $$
begin
  delete from public.team_members where user_id = (select auth.uid());
end $$;
revoke all on function public.leave_team() from public, anon;
grant execute on function public.leave_team() to authenticated;

-- ====================================================================================================
-- FILE: 2026-10-27-multi-teams.sql
-- ====================================================================================================

-- MULTIPLE TEAMS (2026-10-27, notes/26 "Many teams"). User: "allow multiple teams at once".
-- A player can be on up to 10 teams. team_members key = (team_id, user_id); every rule reads "my teams" (a set).
-- Run once on project drhuacxwmlrvaoyjqceg (applied as migration `multi_teams`).

alter table public.team_members drop constraint team_members_pkey;
alter table public.team_members add primary key (team_id, user_id);
create index if not exists team_members_user_idx on public.team_members (user_id);

create or replace function private.my_teams() returns setof uuid
  language sql stable security definer set search_path = '' as $$
  select team_id from public.team_members where user_id = (select auth.uid())
$$;

drop policy "post to team feed" on public.feed;
create policy "post to team feed" on public.feed for insert with check (
  team_id in (select private.my_teams()) and user_id = (select auth.uid())
  and kind = any (array['chat','session','film','share_session','share_film']));
drop policy "read team feed" on public.feed;
create policy "read team feed" on public.feed for select using (team_id in (select private.my_teams()));
drop policy "see self and teammates" on public.profiles;
create policy "see self and teammates" on public.profiles for select using (
  id = (select auth.uid()) or id in (select m.user_id from public.team_members m where m.team_id in (select private.my_teams())));
drop policy "see teammates" on public.team_members;
create policy "see teammates" on public.team_members for select using (team_id in (select private.my_teams()));
drop policy "owner edits team" on public.teams;
create policy "owner edits team" on public.teams for update
  using (id in (select private.my_teams()) and owner = (select auth.uid()))
  with check (id in (select private.my_teams()) and owner = (select auth.uid()));
drop policy "see my team" on public.teams;
create policy "see my teams" on public.teams for select using (id in (select private.my_teams()));

drop function private.my_team();

-- spam guard per team (a finished session is logged to every team you're on)
create or replace function private.feed_rate_limit() returns trigger
  language plpgsql security definer set search_path = '' as $$
begin
  if (select count(*) from public.feed where user_id = new.user_id and team_id = new.team_id
      and created_at > now() - interval '1 minute') >= 8 then
    raise exception 'slow down' using errcode = 'P0001';
  end if;
  return new;
end $$;

create or replace function public.create_team(p_name text, p_logo text default null, p_color integer default 0)
  returns public.teams language plpgsql security definer set search_path = '' as $$
declare uid uuid := (select auth.uid()); t public.teams;
begin
  if uid is null then raise exception 'sign in first'; end if;
  if (select count(*) from public.team_members where user_id = uid) >= 10 then raise exception 'too many teams'; end if;
  insert into public.profiles (id) values (uid) on conflict (id) do nothing;
  insert into public.teams (name, logo, color, code, owner)
    values (trim(p_name), p_logo, coalesce(p_color, 0), private.new_code(), uid) returning * into t;
  insert into public.team_members (user_id, team_id) values (uid, t.id);
  insert into public.feed (team_id, user_id, kind) values (t.id, uid, 'create');
  return t;
end $$;

create or replace function public.join_team(p_code text) returns jsonb
  language plpgsql security definer set search_path = '' as $$
declare uid uuid := (select auth.uid()); t public.teams; granted boolean := false; p public.profiles;
begin
  if uid is null then raise exception 'sign in first'; end if;
  select * into t from public.teams where code = upper(trim(p_code));
  if t.id is null then raise exception 'no team with that code' using errcode = 'P0002'; end if;
  if exists (select 1 from public.team_members where user_id = uid and team_id = t.id) then
    return jsonb_build_object('team_id', t.id, 'trial_granted', false);
  end if;
  if (select count(*) from public.team_members where user_id = uid) >= 10 then raise exception 'too many teams'; end if;
  if (select count(*) from public.team_members where team_id = t.id) >= 30 then raise exception 'team is full'; end if;
  insert into public.profiles (id) values (uid) on conflict (id) do nothing;
  select * into p from public.profiles where id = uid;
  if not p.trial_used then
    update public.profiles set trial_until = now() + interval '7 days', trial_used = true where id = uid;
    granted := true;
  end if;
  insert into public.team_members (user_id, team_id) values (uid, t.id);
  insert into public.feed (team_id, user_id, kind) values (t.id, uid, 'join');
  return jsonb_build_object('team_id', t.id, 'trial_granted', granted);
end $$;

drop function public.leave_team();
-- p_team null = the old app (one team): leave the only team you're on
create or replace function public.leave_team(p_team uuid default null) returns void
  language plpgsql security definer set search_path = '' as $$
declare uid uuid := (select auth.uid()); tid uuid;
begin
  if p_team is null then
    if (select count(*) from public.team_members where user_id = uid) <> 1 then return; end if;
    select team_id into p_team from public.team_members where user_id = uid;
  end if;
  delete from public.team_members where user_id = uid and team_id = p_team returning team_id into tid;
  if tid is null then return; end if;
  if not exists (select 1 from public.team_members where team_id = tid) then
    delete from public.teams where id = tid;               -- last one out: the team and its feed go
  elsif (select owner from public.teams where id = tid) = uid then
    update public.teams set owner = (select user_id from public.team_members where team_id = tid order by joined_at limit 1) where id = tid;
  end if;
end $$;
revoke execute on function public.leave_team(uuid) from public, anon;
grant execute on function public.leave_team(uuid) to authenticated;

-- ====================================================================================================
-- FILE: 2026-10-27-team-streak.sql
-- ====================================================================================================

-- TEAM STREAK (2026-10-27, notes/26 "Team streak"). Run once on project drhuacxwmlrvaoyjqceg.
-- Each player's kept days (10+ min trained) for the last 400 days, as a hex bitmap: bit i (from the left,
-- 4 bits per hex char) = kept_end minus i days. The app works the team streak out from these + team_members.joined_at.
-- Text only, ? 100 chars per player. The app keeps working before this runs (team streak just shows join days).
alter table public.profiles
  add column if not exists kept text,
  add column if not exists kept_end date;
alter table public.profiles drop constraint if exists profiles_kept_len;
alter table public.profiles add constraint profiles_kept_len
  check (kept is null or (length(kept) <= 100 and kept ~ '^[0-9a-f]*$'));

-- ====================================================================================================
-- FILE: 2026-10-28-matchday-pack.sql
-- ====================================================================================================

-- MATCHDAY PACK (2026-10-28, notes/22 "Before launch"). One server pull for everyone instead of every phone
-- calling API-Football (100 calls/day for the whole key). Migration `matchday_pack` on drhuacxwmlrvaoyjqceg.

create table if not exists public.matchday_fixtures (
  id integer primary key,          -- API-Football fixture id
  day text not null,               -- "2026-10-28"
  league integer not null,
  data jsonb not null,             -- the raw fixture, exactly what the app's Fixture decoder reads
  created_at timestamptz not null default now()
);
create index if not exists matchday_fixtures_created_idx on public.matchday_fixtures (created_at desc);

alter table public.matchday_fixtures enable row level security;
-- public match data: anyone with the app can read it; only the edge function (service role) writes
create policy "anyone reads matchday" on public.matchday_fixtures for select using (true);
grant select on public.matchday_fixtures to anon, authenticated;

-- The nightly runs (migration `matchday_cron`). The password is made inside the database and never leaves it.
create extension if not exists pg_cron;
create extension if not exists pg_net;
create extension if not exists pgcrypto with schema extensions;
create table if not exists private.matchday_cron (id int primary key default 1 check (id = 1), secret text not null);
insert into private.matchday_cron (secret) values (encode(extensions.gen_random_bytes(24), 'hex')) on conflict (id) do nothing;
revoke all on private.matchday_cron from public, anon, authenticated;
create or replace function public.matchday_cron_ok(p text) returns boolean
  language sql stable security definer set search_path = '' as $$
  select exists (select 1 from private.matchday_cron where secret = p)
$$;
revoke execute on function public.matchday_cron_ok(text) from public, anon, authenticated;
grant execute on function public.matchday_cron_ok(text) to service_role;

-- 23:50 UTC = Europe's games for the UTC day; 05:30 UTC = the Americas' evening (Brasileirao, MLS) for their day.
select cron.schedule('matchday-pull-europe', '50 23 * * *', $$
  select net.http_post(url := 'https://drhuacxwmlrvaoyjqceg.supabase.co/functions/v1/matchday-pull?tz=UTC',
    headers := jsonb_build_object('x-cron-secret', (select secret from private.matchday_cron)), timeout_milliseconds := 140000)
$$);
select cron.schedule('matchday-pull-americas', '30 5 * * *', $$
  select net.http_post(url := 'https://drhuacxwmlrvaoyjqceg.supabase.co/functions/v1/matchday-pull?tz=America/Sao_Paulo',
    headers := jsonb_build_object('x-cron-secret', (select secret from private.matchday_cron)), timeout_milliseconds := 140000)
$$);

-- ====================================================================================================
-- FILE: 2026-10-28-numeric-team-codes.sql
-- ====================================================================================================

-- 6-DIGIT TEAM CODES (2026-10-28, notes/26 v3). The app's join keypad is numbers only, but the server still made
-- letter+digit codes, so no code it made could be typed in. Independent of the multi-teams file (migration `numeric_team_codes`).

create or replace function private.new_code() returns text
  language plpgsql set search_path = '' as $$
declare c text;
begin
  loop
    c := lpad(floor(random() * 1000000)::int::text, 6, '0');
    exit when not exists (select 1 from public.teams where code = c);
  end loop;
  return c;
end $$;

-- teams made before this keep working: give any letter code a fresh 6-digit one (1 team on 2026-10-28).
-- The old check only allowed [A-Z2-9] (no 0 or 1), so swap it for digits-only around the update. RUN 2026-10-28.
alter table public.teams drop constraint teams_code_check;
update public.teams set code = private.new_code() where code !~ '^[0-9]{6}$';
alter table public.teams add constraint teams_code_check check (code ~ '^[0-9]{6}$');

-- ====================================================================================================
-- FILE: 2026-10-29-backups.sql
-- ====================================================================================================

-- BACKUP (2026-10-29): delete the app, sign back in ? everything is still there.
-- CHEAP ON PURPOSE (user: Caffeine Mog's photo storage cost more than the profits): ONE row per player, ONE small
-- JSON blob (sessions, set log, minutes, streak days, answers, settings ? usually 5?40 KB) + ONE small profile picture
-- (240 px JPEG, ~12 KB, sent only when it changes). No Storage bucket, no files, no videos.
-- The app writes it at most when it goes to the background AND something changed, and reads it once per sign-in.
-- Hard caps below so one player can never grow the bill.

create table if not exists public.backups (
  user_id    uuid primary key default auth.uid() references auth.users (id) on delete cascade,
  data       jsonb not null,
  photo      text,
  updated_at timestamptz not null default now(),
  constraint backups_data_small  check (pg_column_size(data) < 300000),
  constraint backups_photo_small check (photo is null or length(photo) < 40000)
);

alter table public.backups enable row level security;

drop policy if exists "own backup read" on public.backups;
drop policy if exists "own backup insert" on public.backups;
drop policy if exists "own backup update" on public.backups;
create policy "own backup read"   on public.backups for select to authenticated using (user_id = (select auth.uid()));
create policy "own backup insert" on public.backups for insert to authenticated with check (user_id = (select auth.uid()));
create policy "own backup update" on public.backups for update to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));

grant select, insert, update on public.backups to authenticated;

-- ====================================================================================================
-- FILE: 2026-10-29-gift-trials.sql
-- ====================================================================================================

-- GIFT TRIALS + ONE TRIAL PER ACCOUNT (2026-10-29, notes/19 "SHARE LINKS v2").
-- The user: "add on the profile a share for a free 7 day trial no card? Make sure maximum 1 free or card 7 day trial
-- per account". Every player gets ONE personal 6-digit gift code (same number space as team codes, never the same
-- number, so the one code box + soccermax.app/join/<code> work for both). A friend who redeems it gets 7 days free, no
-- card ? only if their account never had a trial: profiles.trial_used is the single flag for team trials, gift trials
-- AND Apple's card trial (the app calls mark_trial_used() once Apple says the free trial was used). trial_* columns are
-- SELECT-only for the app, so only these functions can change them. Migration `gift_trials`.

create table if not exists public.gifts (
  code text primary key check (code ~ '^[0-9]{6}$'),
  owner uuid not null unique references auth.users (id) on delete cascade,
  uses integer not null default 0,
  created_at timestamptz not null default now()
);
alter table public.gifts enable row level security;   -- no policies: only the functions below touch it

create or replace function private.new_code() returns text
  language plpgsql set search_path = '' as $$
declare c text;
begin
  loop
    c := lpad(floor(random() * 1000000)::int::text, 6, '0');
    exit when not exists (select 1 from public.teams where code = c)
          and not exists (select 1 from public.gifts where code = c);
  end loop;
  return c;
end $$;

-- your own gift code (made the first time you ask)
create or replace function public.my_gift_code() returns text
  language plpgsql security definer set search_path = '' as $$
declare uid uuid := (select auth.uid()); c text;
begin
  if uid is null then raise exception 'sign in first'; end if;
  select code into c from public.gifts where owner = uid;
  if c is null then
    insert into public.gifts (code, owner) values (private.new_code(), uid) returning code into c;
  end if;
  return c;
end $$;

-- who the gift is from (first name only)
create or replace function public.gift_preview(p_code text) returns table (name text)
  language sql stable security definer set search_path = '' as $$
  select coalesce(nullif(split_part(trim(p.name), ' ', 1), ''), 'A friend')
  from public.gifts g left join public.profiles p on p.id = g.owner
  where g.code = trim(p_code) and (select auth.uid()) is not null
$$;

create or replace function public.redeem_gift(p_code text) returns jsonb
  language plpgsql security definer set search_path = '' as $$
declare uid uuid := (select auth.uid()); g public.gifts; p public.profiles; granted boolean := false;
begin
  if uid is null then raise exception 'sign in first'; end if;
  select * into g from public.gifts where code = trim(p_code);
  if g.code is null then raise exception 'no gift with that code' using errcode = 'P0002'; end if;
  if g.owner = uid then raise exception 'that is your own code'; end if;
  insert into public.profiles (id) values (uid) on conflict (id) do nothing;
  select * into p from public.profiles where id = uid for update;
  if not p.trial_used then
    update public.profiles set trial_until = now() + interval '7 days', trial_used = true where id = uid;
    update public.gifts set uses = uses + 1 where code = g.code;
    granted := true;
  end if;
  return jsonb_build_object('trial_granted', granted);
end $$;

-- Apple's card trial was used on this Apple ID ? no free week on top (it can only ever switch the flag on)
create or replace function public.mark_trial_used() returns void
  language plpgsql security definer set search_path = '' as $$
declare uid uuid := (select auth.uid());
begin
  if uid is null then return; end if;
  insert into public.profiles (id) values (uid) on conflict (id) do nothing;
  update public.profiles set trial_used = true where id = uid and not trial_used;
end $$;

revoke all on function public.my_gift_code(), public.gift_preview(text), public.redeem_gift(text), public.mark_trial_used() from public, anon;
grant execute on function public.my_gift_code(), public.gift_preview(text), public.redeem_gift(text), public.mark_trial_used() to authenticated;

-- ====================================================================================================
-- FILE: 2026-10-30-lifetime-codes.sql
-- ====================================================================================================

-- FREE LIFETIME CODES (2026-10-30, notes/40). The user: "instead of just team code, change it to 'Have a code' and
-- ? generate 100 free codes that when typed in grant lifetime free pass". 100 one-use 6-digit codes in the same
-- number space as team + gift codes (so the one HAVE A CODE box takes all three, never two the same number).
-- Redeem ? profiles.free_for_life = true + trial_until far in the future (so the app's existing access check opens).
-- Both columns are SELECT-only for the app (column grants), so only these functions can set them. Codes never live
-- in the app ? the list is on the PostHog "? Free Codes" dashboard (app/scripts/posthog-codes.mjs).
-- RUN 2026-10-30 (migrations lifetime_codes + lifetime_codes_miss_fix).
-- Guessing is limited: 10 wrong lifetime tries per account per hour.

alter table public.profiles add column if not exists free_for_life boolean not null default false;

create table if not exists public.lifetime_codes (
  code text primary key check (code ~ '^[0-9]{6}$'),
  redeemed_by uuid unique references auth.users (id) on delete set null,
  redeemed_at timestamptz,
  created_at timestamptz not null default now()
);
alter table public.lifetime_codes enable row level security;   -- no policies: only the functions below touch it

create table if not exists private.code_misses (uid uuid not null, at timestamptz not null default now());
create index if not exists code_misses_uid_at on private.code_misses (uid, at);

-- new team / gift codes never take a lifetime code's number
create or replace function private.new_code() returns text
  language plpgsql set search_path = '' as $$
declare c text;
begin
  loop
    c := lpad(floor(random() * 1000000)::int::text, 6, '0');
    exit when not exists (select 1 from public.teams where code = c)
          and not exists (select 1 from public.gifts where code = c)
          and not exists (select 1 from public.lifetime_codes where code = c);
  end loop;
  return c;
end $$;

-- the 100 codes (only when the table is empty, so re-running never makes more)
do $$
begin
  if not exists (select 1 from public.lifetime_codes) then
    for i in 1..100 loop
      insert into public.lifetime_codes (code) values (private.new_code());
    end loop;
  end if;
end $$;

-- is this an unused lifetime code? (a wrong guess counts toward the 10-per-hour limit). Misses are RETURNED, never
-- raised ? a raise would roll back the miss row and the limit would never count.
create or replace function public.lifetime_preview(p_code text) returns boolean
  language plpgsql security definer set search_path = '' as $$
declare me uuid := (select auth.uid()); ok boolean;
begin
  if me is null then return false; end if;
  if (select count(*) from private.code_misses where code_misses.uid = me and at > now() - interval '1 hour') >= 10 then
    return false;
  end if;
  select (redeemed_by is null or redeemed_by = me) into ok from public.lifetime_codes where code = trim(p_code);
  if ok is null then insert into private.code_misses (uid) values (me); end if;
  return coalesce(ok, false);
end $$;

-- {lifetime: true} or {lifetime: false, error: "?"}
create or replace function public.redeem_lifetime(p_code text) returns jsonb
  language plpgsql security definer set search_path = '' as $$
declare me uuid := (select auth.uid()); c public.lifetime_codes;
begin
  if me is null then raise exception 'sign in first'; end if;
  if (select count(*) from private.code_misses where code_misses.uid = me and at > now() - interval '1 hour') >= 10 then
    return jsonb_build_object('lifetime', false, 'error', 'Too many tries. Wait an hour and try again.');
  end if;
  select * into c from public.lifetime_codes where code = trim(p_code) for update;
  if c.code is null then
    insert into private.code_misses (uid) values (me);
    return jsonb_build_object('lifetime', false, 'error', 'That code doesn''t work.');
  end if;
  if c.redeemed_by is not null and c.redeemed_by <> me then
    return jsonb_build_object('lifetime', false, 'error', 'That code was already used.');
  end if;
  update public.lifetime_codes set redeemed_by = me, redeemed_at = coalesce(redeemed_at, now()) where code = c.code;
  insert into public.profiles (id) values (me) on conflict (id) do nothing;
  update public.profiles set free_for_life = true, trial_until = '2999-12-31T00:00:00Z' where id = me;
  return jsonb_build_object('lifetime', true);
end $$;

revoke all on function public.lifetime_preview(text), public.redeem_lifetime(text) from public, anon;
grant execute on function public.lifetime_preview(text), public.redeem_lifetime(text) to authenticated;

-- ====================================================================================================
-- FILE: 2026-10-30-safety.sql
-- ====================================================================================================

-- 2026-10-30 ? App Store safety: block + report in team chat (Guideline 1.2) and in-app account deletion (5.1.1(v)).
-- Safe to re-run. Applied to drhuacxwmlrvaoyjqceg by MCP 2026-10-30.

-- BLOCKS: I never see posts from someone I blocked (the feed read rule below hides them on the server).
create table if not exists public.blocks (
  blocker uuid not null default auth.uid() references auth.users (id) on delete cascade,
  blocked uuid not null references auth.users (id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (blocker, blocked)
);
alter table public.blocks enable row level security;
drop policy if exists "see own blocks" on public.blocks;
create policy "see own blocks" on public.blocks for select to authenticated using (blocker = (select auth.uid()));
drop policy if exists "add own blocks" on public.blocks;
create policy "add own blocks" on public.blocks for insert to authenticated with check (blocker = (select auth.uid()) and blocked <> (select auth.uid()));
drop policy if exists "remove own blocks" on public.blocks;
create policy "remove own blocks" on public.blocks for delete to authenticated using (blocker = (select auth.uid()));

-- the feed: my teams' posts, minus anyone I blocked
drop policy if exists "read team feed" on public.feed;
create policy "read team feed" on public.feed for select to authenticated using (
  team_id in (select private.my_teams())
  and user_id not in (select b.blocked from public.blocks b where b.blocker = (select auth.uid()))
);

-- REPORTS: written only through report_post (keeps a copy of the message, even if it's deleted later). Nobody can read
-- them from the app ? the developer reviews them in the Supabase dashboard (Table editor ? reports) within 24 h.
create table if not exists public.reports (
  id bigint generated always as identity primary key,
  reporter uuid references auth.users (id) on delete set null,
  reported uuid,
  post_id bigint,
  team_id uuid,
  kind text,
  body text,
  reason text not null,
  created_at timestamptz not null default now(),
  handled boolean not null default false
);
alter table public.reports enable row level security;   -- no policies: no direct reads or writes

create or replace function public.report_post(p_post bigint, p_reason text)
returns void language plpgsql security definer set search_path = '' as $$
declare f public.feed%rowtype;
begin
  select * into f from public.feed where id = p_post and team_id in (select private.my_teams());
  if not found then raise exception 'Message not found'; end if;
  insert into public.reports (reporter, reported, post_id, team_id, kind, body, reason)
  values ((select auth.uid()), f.user_id, f.id, f.team_id, f.kind, f.body, left(coalesce(p_reason, 'Other'), 60));
end $$;

create or replace function public.report_player(p_user uuid, p_reason text)
returns void language plpgsql security definer set search_path = '' as $$
begin
  if not exists (select 1 from public.team_members where user_id = p_user and team_id in (select private.my_teams())) then
    raise exception 'Player not found';
  end if;
  insert into public.reports (reporter, reported, reason) values ((select auth.uid()), p_user, left(coalesce(p_reason, 'Other'), 60));
end $$;

-- DELETE MY ACCOUNT: removes the sign-in account; profiles, team memberships, posts, backups and gift codes all cascade.
-- Teams left with nobody on them go too.
create or replace function public.delete_my_account()
returns void language plpgsql security definer set search_path = '' as $$
declare me uuid := (select auth.uid());
begin
  if me is null then raise exception 'Not signed in'; end if;
  delete from auth.users where id = me;
  delete from public.teams t where not exists (select 1 from public.team_members m where m.team_id = t.id);
end $$;

revoke all on function public.report_post(bigint, text) from public, anon;
revoke all on function public.report_player(uuid, text) from public, anon;
revoke all on function public.delete_my_account() from public, anon;
grant execute on function public.report_post(bigint, text) to authenticated;
grant execute on function public.report_player(uuid, text) to authenticated;
grant execute on function public.delete_my_account() to authenticated;

-- ====================================================================================================
-- FILE: 2026-11-01-waitlist.sql
-- ====================================================================================================

-- soccermax.app launch WAITLIST (2026-11-01, notes/38 ? site). Emails from the site / TikTok bio page until the app is live.
-- Nobody can read or change the table from outside: no policies, RLS on. The ONLY way in is join_waitlist() (adds one
-- email, 13+ ticked on the page), called by the site's Cloudflare worker. Read it in the Supabase dashboard / service key.
create table if not exists public.waitlist (
  email      text primary key check (email = lower(email) and length(email) between 6 and 254 and email ~ '^[^\s@]+@[^\s@]+\.[^\s@]{2,}$'),
  src        text check (length(src) <= 40),
  country    text check (length(country) <= 4),
  created_at timestamptz not null default now()
);
alter table public.waitlist enable row level security;
revoke all on public.waitlist from anon, authenticated;

create or replace function public.join_waitlist(p_email text, p_src text default null, p_country text default null)
returns boolean            -- true = new on the list, false = was already on it
language plpgsql security definer set search_path = public as $$
declare e text := lower(trim(p_email));
begin
  insert into public.waitlist (email, src, country) values (e, left(p_src, 40), left(p_country, 4))
  on conflict (email) do nothing;
  return found;
end $$;
revoke all on function public.join_waitlist(text, text, text) from public;
grant execute on function public.join_waitlist(text, text, text) to anon;

-- ====================================================================================================
-- FILE: 2026-11-01-waitlist-codes.sql
-- ====================================================================================================

-- WAITLIST 40% OFF CODES (2026-11-01). User: "if they put in their email they get 40% off and that's the whole selling
-- point. The launch day email should give them the code for at checkout."
-- Every waitlist email gets its own one-use 6-digit code, in the same number space as team / gift / lifetime codes
-- (one HAVE A CODE box takes them all). In the app: HAVE A CODE ? off40_preview ? redeem_off40 ? the 40% OFF plans
-- (the .off40 products, StayOfferView launch mode ? no 10-minute clock). The launch email sends each person their code.
-- One code = one account; the same account can use it again (closed the page, came back). RUN 2026-11-01.

alter table public.waitlist add column if not exists code text unique check (code ~ '^[0-9]{6}$');
alter table public.waitlist add column if not exists redeemed_by uuid references auth.users (id) on delete set null;
alter table public.waitlist add column if not exists redeemed_at timestamptz;

-- new codes never take a number that's already a team, gift, lifetime or waitlist code
create or replace function private.new_code() returns text
  language plpgsql set search_path = '' as $$
declare c text;
begin
  loop
    c := lpad(floor(random() * 1000000)::int::text, 6, '0');
    exit when not exists (select 1 from public.teams where code = c)
          and not exists (select 1 from public.gifts where code = c)
          and not exists (select 1 from public.lifetime_codes where code = c)
          and not exists (select 1 from public.waitlist where code = c);
  end loop;
  return c;
end $$;

-- sign-up: email in, code made now (sent in the launch email). true = new on the list.
create or replace function public.join_waitlist(p_email text, p_src text default null, p_country text default null)
returns boolean
language plpgsql security definer set search_path = public as $$
declare e text := lower(trim(p_email));
begin
  insert into public.waitlist (email, src, country, code) values (e, left(p_src, 40), left(p_country, 4), private.new_code())
  on conflict (email) do nothing;
  return found;
end $$;
revoke all on function public.join_waitlist(text, text, text) from public;
grant execute on function public.join_waitlist(text, text, text) to anon;

update public.waitlist set code = private.new_code() where code is null;
alter table public.waitlist alter column code set not null;

-- is this a 40% OFF code this account can use? (wrong guesses count toward the same 10-per-hour limit)
create or replace function public.off40_preview(p_code text) returns boolean
  language plpgsql security definer set search_path = '' as $$
declare me uuid := (select auth.uid()); ok boolean;
begin
  if me is null then return false; end if;
  if (select count(*) from private.code_misses where code_misses.uid = me and at > now() - interval '1 hour') >= 10 then
    return false;
  end if;
  select (redeemed_by is null or redeemed_by = me) into ok from public.waitlist where code = trim(p_code);
  if ok is null then insert into private.code_misses (uid) values (me); end if;
  return coalesce(ok, false);
end $$;

-- {ok: true} or {ok: false, error: "?"}
create or replace function public.redeem_off40(p_code text) returns jsonb
  language plpgsql security definer set search_path = '' as $$
declare me uuid := (select auth.uid()); w public.waitlist;
begin
  if me is null then raise exception 'sign in first'; end if;
  if (select count(*) from private.code_misses where code_misses.uid = me and at > now() - interval '1 hour') >= 10 then
    return jsonb_build_object('ok', false, 'error', 'Too many tries. Wait an hour and try again.');
  end if;
  select * into w from public.waitlist where code = trim(p_code) for update;
  if w.code is null then
    insert into private.code_misses (uid) values (me);
    return jsonb_build_object('ok', false, 'error', 'That code doesn''t work.');
  end if;
  if w.redeemed_by is not null and w.redeemed_by <> me then
    return jsonb_build_object('ok', false, 'error', 'That code was already used.');
  end if;
  update public.waitlist set redeemed_by = me, redeemed_at = coalesce(redeemed_at, now()) where code = w.code;
  return jsonb_build_object('ok', true);
end $$;

revoke all on function public.off40_preview(text) from public;
revoke all on function public.redeem_off40(text) from public;
grant execute on function public.off40_preview(text) to authenticated;
grant execute on function public.redeem_off40(text) to authenticated;

-- ====================================================================================================
-- FILE: 2026-11-08-local-teams.sql
-- ====================================================================================================

-- LOCAL TEAMS + JOIN REQUESTS (2026-11-08, notes/26 top). User: "allow the option for teams to select a location when
-- being created or after being created so local players can see them and request to join. Only the creator of the
-- group should be able to alter these settings and accept requests."
-- Additive only. A team with a place shows up to nearby players (rounded to ~1 km ? never an exact pitch/house);
-- they REQUEST to join; only the team's owner sees and answers requests. Applied as migration `local_teams`.

alter table public.teams add column if not exists place text;
alter table public.teams add column if not exists lat double precision;
alter table public.teams add column if not exists lng double precision;
create index if not exists teams_located_idx on public.teams (lat, lng) where lat is not null;

create table if not exists public.join_requests (
  team_id uuid not null references public.teams (id) on delete cascade,
  user_id uuid not null references public.profiles (id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (team_id, user_id)
);
create index if not exists join_requests_user_idx on public.join_requests (user_id);
alter table public.join_requests enable row level security;
-- no direct table access: everything goes through the functions below
revoke all on public.join_requests from anon, authenticated;

-- owner only: set (or clear with nulls) where the team plays. ~1 km rounding happens here.
create or replace function public.set_team_location(p_team uuid, p_place text, p_lat double precision, p_lng double precision)
  returns void language plpgsql security definer set search_path = '' as $$
begin
  if (select owner from public.teams where id = p_team) is distinct from (select auth.uid()) then
    raise exception 'only the team creator can change this' using errcode = '42501';
  end if;
  update public.teams set
    place = nullif(left(trim(coalesce(p_place, '')), 60), ''),
    lat = case when p_lat is null then null else round(p_lat::numeric, 2)::double precision end,
    lng = case when p_lng is null then null else round(p_lng::numeric, 2)::double precision end
  where id = p_team;
end $$;

-- teams near a point (that set a place), not ones I'm already on. Only name/crest/place/size/distance leave the server.
create or replace function public.nearby_teams(p_lat double precision, p_lng double precision, p_km double precision default 30)
  returns table (id uuid, name text, logo text, color integer, place text, members integer, km double precision, requested boolean)
  language sql stable security definer set search_path = '' as $$
  select t.id, t.name, t.logo, t.color, t.place,
         (select count(*)::int from public.team_members m where m.team_id = t.id) as members,
         round((6371 * 2 * asin(sqrt(power(sin(radians(t.lat - p_lat) / 2), 2)
           + cos(radians(p_lat)) * cos(radians(t.lat)) * power(sin(radians(t.lng - p_lng) / 2), 2))))::numeric, 1)::double precision as km,
         exists (select 1 from public.join_requests r where r.team_id = t.id and r.user_id = (select auth.uid())) as requested
  from public.teams t
  where t.lat is not null
    and (select auth.uid()) is not null
    and t.lat between p_lat - p_km / 111.0 and p_lat + p_km / 111.0
    and t.id not in (select team_id from public.team_members where user_id = (select auth.uid()))
  order by km
  limit 25
$$;

create or replace function public.request_join(p_team uuid) returns void
  language plpgsql security definer set search_path = '' as $$
declare uid uuid := (select auth.uid());
begin
  if uid is null then raise exception 'sign in first'; end if;
  if (select lat from public.teams where id = p_team) is null then raise exception 'that team is not open to requests'; end if;
  if exists (select 1 from public.team_members where team_id = p_team and user_id = uid) then return; end if;
  if (select count(*) from public.join_requests where user_id = uid) >= 10 then raise exception 'too many open requests'; end if;
  insert into public.profiles (id) values (uid) on conflict (id) do nothing;
  insert into public.join_requests (team_id, user_id) values (p_team, uid) on conflict do nothing;
end $$;

create or replace function public.cancel_request(p_team uuid) returns void
  language sql security definer set search_path = '' as $$
  delete from public.join_requests where team_id = p_team and user_id = (select auth.uid())
$$;

-- owner only: who asked to join
create or replace function public.team_requests(p_team uuid)
  returns table (user_id uuid, name text, "position" text, level integer, created_at timestamptz)
  language sql stable security definer set search_path = '' as $$
  select r.user_id, coalesce(p.name, 'Player'), p.position, p.level, r.created_at
  from public.join_requests r join public.profiles p on p.id = r.user_id
  join public.teams t on t.id = r.team_id
  where r.team_id = p_team and t.owner = (select auth.uid())
  order by r.created_at
$$;

-- owner only: accept (joins the team, shows in the feed) or decline. Either way the request goes.
create or replace function public.answer_request(p_team uuid, p_user uuid, p_accept boolean) returns void
  language plpgsql security definer set search_path = '' as $$
begin
  if (select owner from public.teams where id = p_team) is distinct from (select auth.uid()) then
    raise exception 'only the team creator can answer requests' using errcode = '42501';
  end if;
  if not exists (select 1 from public.join_requests where team_id = p_team and user_id = p_user) then return; end if;
  delete from public.join_requests where team_id = p_team and user_id = p_user;
  if p_accept and not exists (select 1 from public.team_members where team_id = p_team and user_id = p_user) then
    if (select count(*) from public.team_members where team_id = p_team) >= 30 then raise exception 'team is full'; end if;
    if (select count(*) from public.team_members where user_id = p_user) >= 10 then raise exception 'that player is on too many teams'; end if;
    insert into public.team_members (user_id, team_id) values (p_user, p_team);
    insert into public.feed (team_id, user_id, kind) values (p_team, p_user, 'join');
  end if;
end $$;

do $$ declare f text; begin
  foreach f in array array['set_team_location(uuid,text,double precision,double precision)',
    'nearby_teams(double precision,double precision,double precision)', 'request_join(uuid)', 'cancel_request(uuid)',
    'team_requests(uuid)', 'answer_request(uuid,uuid,boolean)'] loop
    execute format('revoke execute on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
end $$;

-- ====================================================================================================
-- FILE: 2026-11-08-map-teams.sql
-- ====================================================================================================

-- MAP TEAMS (2026-11-08, notes/19 top). User: "put teams on the map with a person type icon, only applies to teams who
-- put in their location". Read-only and additive: teams that set a place (lat/lng already rounded to ~1 km by
-- set_team_location) near a point, plus every located team I'm on. Only name/colour/place/size/spot leave the server.
-- Applied as migration `map_teams`.
create or replace function public.map_teams(p_lat double precision, p_lng double precision, p_km double precision default 50)
  returns table (id uuid, name text, color integer, place text, members integer,
                 lat double precision, lng double precision, mine boolean, requested boolean)
  language sql stable security definer set search_path = '' as $$
  select t.id, t.name, t.color, t.place,
         (select count(*)::int from public.team_members m where m.team_id = t.id) as members,
         t.lat, t.lng,
         exists (select 1 from public.team_members m where m.team_id = t.id and m.user_id = (select auth.uid())) as mine,
         exists (select 1 from public.join_requests r where r.team_id = t.id and r.user_id = (select auth.uid())) as requested
  from public.teams t
  where t.lat is not null and t.lng is not null
    and (select auth.uid()) is not null
    and (
      exists (select 1 from public.team_members m where m.team_id = t.id and m.user_id = (select auth.uid()))
      or (t.lat between p_lat - p_km / 111.0 and p_lat + p_km / 111.0
          and t.lng between p_lng - p_km / (111.0 * greatest(cos(radians(p_lat)), 0.2))
                        and p_lng + p_km / (111.0 * greatest(cos(radians(p_lat)), 0.2)))
    )
  limit 80
$$;
revoke execute on function public.map_teams(double precision, double precision, double precision) from public, anon;
grant execute on function public.map_teams(double precision, double precision, double precision) to authenticated;

-- ====================================================================================================
-- FILE: 2026-11-08-session-media.sql
-- ====================================================================================================

-- SESSION MEDIA (2026-11-08): photos/videos a player adds to a session, shown in their teams' feeds.
-- Private bucket. Path = <owner uid>/<file>. Owner uploads/deletes their own; teammates (anyone sharing a team) can read.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('session-media', 'session-media', false, 52428800,
        array['image/jpeg','image/png','image/heic','video/mp4','video/quicktime'])
on conflict (id) do nothing;

create policy "session media: upload own" on storage.objects for insert to authenticated
  with check (bucket_id = 'session-media' and (storage.foldername(name))[1] = (select auth.uid())::text);

create policy "session media: delete own" on storage.objects for delete to authenticated
  using (bucket_id = 'session-media' and (storage.foldername(name))[1] = (select auth.uid())::text);

create policy "session media: owner and teammates read" on storage.objects for select to authenticated
  using (bucket_id = 'session-media' and (
    (storage.foldername(name))[1] = (select auth.uid())::text
    or exists (select 1 from public.team_members m
               where m.user_id::text = (storage.foldername(name))[1]
                 and m.team_id in (select private.my_teams()))));

-- ====================================================================================================
-- FILE: 2026-11-12-creators.sql
-- ====================================================================================================

-- CREATOR (AFFILIATE) PROGRAM (2026-11-12). A content creator gets ONE 6-digit code in the same number space as team,
-- gift, lifetime and 40%-off codes, so the app's one HAVE A CODE box and the existing invite link
-- (soccermax.app/join/<code>) work for creators with no website change. A viewer who opens the link or types the code
-- is tied to that creator; the creator earns `rate` (default 10%) of what we actually receive from that viewer
-- (price minus store commission and tax) for `months` months (default 12) after the viewer was tied to them.
--
-- Money never moves here: purchases come in from RevenueCat's webhook (functions/revenuecat-webhook), each one is
-- written once to purchase_events with the commission worked out at that moment, and payouts you send by hand
-- (PayPal, bank, Wise) are noted in creator_payouts. Nothing in this file is readable or writable from the app except
-- the functions granted at the bottom: every table has Row Level Security on and NO policies.
--
-- Run once in the Supabase SQL editor (safe to re-run). Then:
--   select * from public.new_creator('Alex Smith', 'alex@example.com');     -- makes a creator, returns code + links
--   select * from public.creator_balances;                                    -- who is owed what
--   insert into public.creator_payouts (creator_id, amount_usd, note) values ('<id>', 42.10, 'PayPal 2026-12-01');

-- ---------------------------------------------------------------------------------------------------------------
-- tables
-- ---------------------------------------------------------------------------------------------------------------

create table if not exists public.creators (
  id uuid primary key default gen_random_uuid(),
  code text not null unique check (code ~ '^[0-9]{6}$'),
  name text not null check (length(name) between 1 and 60),          -- shown to viewers: "Alex Smith's code"
  email text,                                                        -- where to reach / pay them (never sent to the app)
  user_id uuid references auth.users (id) on delete set null,        -- their own app account, if any (blocks self-referral)
  rate numeric(5,4) not null default 0.10 check (rate >= 0 and rate <= 0.5),
  months integer check (months is null or months between 1 and 120) default 12,   -- null = every payment, forever
  dashboard_key uuid not null default gen_random_uuid(),             -- the secret in the creator's private stats link
  active boolean not null default true,
  created_at timestamptz not null default now()
);
alter table public.creators enable row level security;

-- one row per customer: who brought them. `app_user_id` is RevenueCat's id for the customer = the Supabase user id once
-- they sign in with Apple, or RevenueCat's anonymous id when they bought before signing in.
create table if not exists public.creator_referrals (
  app_user_id text primary key,
  user_id uuid,                                   -- no foreign key: the money record outlives a deleted account
  creator_id uuid not null references public.creators (id),
  source text not null default 'code' check (source in ('code', 'purchase')),
  attributed_at timestamptz not null default now()
);
create index if not exists creator_referrals_creator on public.creator_referrals (creator_id);
create unique index if not exists creator_referrals_user on public.creator_referrals (user_id) where user_id is not null;
alter table public.creator_referrals enable row level security;

-- every RevenueCat event, once (event_id is RevenueCat's id, the same on retries).
create table if not exists public.purchase_events (
  event_id text primary key,
  type text not null,
  environment text,
  app_user_id text,
  ids text[] not null default '{}',               -- every id RevenueCat knows this customer by
  product_id text,
  store text,
  period_type text,
  transaction_id text,
  original_transaction_id text,
  currency text,
  price_usd numeric(12,4) not null default 0,     -- what the customer paid, in USD (negative = refund)
  net_usd numeric(12,4) not null default 0,       -- what we keep after the store's cut and tax
  creator_id uuid references public.creators (id),
  rate numeric(5,4),
  commission_usd numeric(12,4) not null default 0,
  event_at timestamptz not null,
  received_at timestamptz not null default now()
);
create index if not exists purchase_events_creator on public.purchase_events (creator_id, event_at);
create index if not exists purchase_events_tx on public.purchase_events (transaction_id);
create index if not exists purchase_events_ids on public.purchase_events using gin (ids);
alter table public.purchase_events enable row level security;

create table if not exists public.creator_payouts (
  id bigint generated always as identity primary key,
  creator_id uuid not null references public.creators (id),
  amount_usd numeric(12,2) not null check (amount_usd > 0),
  note text,
  paid_at timestamptz not null default now()
);
alter table public.creator_payouts enable row level security;

-- belt and braces: the app's roles get nothing on these tables even if a policy is added by mistake later
revoke all on public.creators, public.creator_referrals, public.purchase_events, public.creator_payouts from anon, authenticated;

-- ---------------------------------------------------------------------------------------------------------------
-- codes: creator codes share the one 6-digit number space
-- ---------------------------------------------------------------------------------------------------------------

create or replace function private.new_code() returns text
  language plpgsql set search_path = '' as $$
declare c text;
begin
  loop
    c := lpad(floor(random() * 1000000)::int::text, 6, '0');
    exit when not exists (select 1 from public.teams where code = c)
          and not exists (select 1 from public.gifts where code = c)
          and not exists (select 1 from public.lifetime_codes where code = c)
          and not exists (select 1 from public.waitlist where code = c)
          and not exists (select 1 from public.creators where code = c);
  end loop;
  return c;
end $$;

-- make a creator (SQL editor / service role only). Returns what to send them.
create or replace function public.new_creator(p_name text, p_email text default null, p_rate numeric default 0.10, p_months integer default 12)
  returns table (creator_id uuid, creator_code text, share_link text, stats_link text)
  language plpgsql security definer set search_path = '' as $$
declare c public.creators;
begin
  insert into public.creators (code, name, email, rate, months)
    values (private.new_code(), trim(p_name), nullif(trim(p_email), ''), p_rate, p_months)
    returning * into c;
  return query select c.id, c.code,
    'https://soccermax.app/join/' || c.code,
    'https://soccermax.app/creator#' || c.code || '.' || c.dashboard_key::text;
end $$;
revoke all on function public.new_creator(text, text, numeric, integer) from public, anon, authenticated;
grant execute on function public.new_creator(text, text, numeric, integer) to service_role;

-- ---------------------------------------------------------------------------------------------------------------
-- the app: is this a creator code? / tie me to this creator
-- ---------------------------------------------------------------------------------------------------------------

-- the creator's display name, or null. Locked out while the account is over the shared 10-wrong-codes-per-hour limit
-- (private.code_misses), but a miss here is not counted: the app asks this for every code that isn't a team or gift,
-- and all it can reveal is a creator's public name.
create or replace function public.creator_preview(p_code text) returns text
  language plpgsql stable security definer set search_path = '' as $$
declare me uuid := (select auth.uid()); n text;
begin
  if me is null then return null; end if;
  if (select count(*) from private.code_misses where code_misses.uid = me and at > now() - interval '1 hour') >= 10 then
    return null;
  end if;
  select name into n from public.creators where code = trim(p_code) and active;
  return n;
end $$;

-- {ok: true, name: "Alex"} or {ok: false, error: "..."}. First creator wins and is never replaced; an account that
-- has already paid can't be tied to a creator afterwards (that would hand out commission for a customer they didn't
-- bring). A wrong code is NOT counted as a miss here: the app calls this quietly with whatever code came from a link
-- (it may be a team code), and guessing creator codes through it gains nothing.
create or replace function public.claim_creator(p_code text) returns jsonb
  language plpgsql security definer set search_path = '' as $$
declare me uuid := (select auth.uid()); c public.creators; mine public.creator_referrals;
begin
  if me is null then raise exception 'sign in first'; end if;
  select * into c from public.creators where code = trim(p_code) and active;
  if c.id is null then return jsonb_build_object('ok', false, 'error', 'That code doesn''t work.'); end if;

  select * into mine from public.creator_referrals where app_user_id = me::text or user_id = me limit 1;
  if mine.creator_id is not null then
    if mine.creator_id = c.id then return jsonb_build_object('ok', true, 'name', c.name); end if;
    return jsonb_build_object('ok', false, 'error', 'This account already used a creator code.');
  end if;
  if c.user_id = me then return jsonb_build_object('ok', false, 'error', 'You can''t use your own code.'); end if;
  if exists (select 1 from public.purchase_events e
             where e.ids @> array[me::text] and e.environment = 'PRODUCTION' and e.price_usd > 0) then
    return jsonb_build_object('ok', false, 'error', 'Creator codes only work before your first purchase.');
  end if;

  insert into public.creator_referrals (app_user_id, user_id, creator_id, source)
    values (me::text, me, c.id, 'code')
    on conflict do nothing;
  return jsonb_build_object('ok', true, 'name', c.name);
end $$;

revoke all on function public.creator_preview(text), public.claim_creator(text) from public, anon;
grant execute on function public.creator_preview(text), public.claim_creator(text) to authenticated;

-- ---------------------------------------------------------------------------------------------------------------
-- RevenueCat webhook -> one row per event, commission worked out here (service role only)
-- ---------------------------------------------------------------------------------------------------------------

create or replace function public.record_purchase_event(p jsonb) returns text
  language plpgsql security definer set search_path = '' as $$
declare
  eid text := p->>'id';
  typ text := coalesce(p->>'type', '');
  env text := p->>'environment';
  v_ids text[];
  at_ timestamptz := to_timestamp(coalesce((p->>'event_timestamp_ms')::numeric, extract(epoch from now()) * 1000) / 1000.0);
  price numeric := coalesce((p->>'price')::numeric, 0);
  tax numeric := (p->>'tax_percentage')::numeric;
  cut numeric := (p->>'commission_percentage')::numeric;
  keep numeric;
  net numeric;
  ref public.creator_referrals;
  c public.creators;
  tag text := p #>> '{subscriber_attributes,creator_code,value}';
  prior public.purchase_events;
  r numeric;
  com numeric := 0;
  who uuid;
begin
  if eid is null or eid = '' then return 'no id'; end if;
  if exists (select 1 from public.purchase_events where event_id = eid) then return 'duplicate'; end if;

  -- every id for this customer (the current one, the first one, and any RevenueCat merged into it)
  select coalesce(array_agg(distinct x), '{}') into v_ids from (
    select p->>'app_user_id' as x
    union select p->>'original_app_user_id'
    union select jsonb_array_elements_text(case when jsonb_typeof(p->'aliases') = 'array' then p->'aliases' else '[]'::jsonb end)
  ) s where x is not null and x <> '';

  -- what we keep: price minus the store's cut and tax. Unknown cut = 30% (the worst case), so we never overpay.
  if tax is not null or cut is not null then keep := 1 - coalesce(tax, 0) - coalesce(cut, 0.30);
  elsif (p->>'takehome_percentage') is not null then keep := (p->>'takehome_percentage')::numeric;
  else keep := 0.70;
  end if;
  keep := greatest(0, least(1, keep));
  net := round(price * keep, 4);

  select * into ref from public.creator_referrals where app_user_id = any(v_ids) order by attributed_at limit 1;

  -- bought before signing in: the app tagged the RevenueCat customer with the code from the link. Tie them now,
  -- (a free-trial start counts), but never once they have already paid (same rule as claim_creator).
  if ref.creator_id is null and tag is not null and env = 'PRODUCTION'
     and typ in ('INITIAL_PURCHASE', 'NON_RENEWING_PURCHASE', 'RENEWAL')
     and not exists (select 1 from public.purchase_events e where e.ids && v_ids and e.environment = 'PRODUCTION' and e.price_usd > 0) then
    select * into c from public.creators where code = trim(tag) and active;
    if c.id is not null and (c.user_id is null or not (c.user_id::text = any(v_ids))) then
      insert into public.creator_referrals (app_user_id, user_id, creator_id, source, attributed_at)
        values (coalesce(p->>'original_app_user_id', p->>'app_user_id'), null, c.id, 'purchase', at_)
        on conflict do nothing;
      select * into ref from public.creator_referrals where app_user_id = any(v_ids) order by attributed_at limit 1;
    end if;
  end if;

  if ref.creator_id is not null then select * into c from public.creators where id = ref.creator_id; end if;

  -- commission: real money only (never sandbox), on purchases and renewals inside the creator's window
  if c.id is not null and env = 'PRODUCTION' then
    if price > 0 and typ in ('INITIAL_PURCHASE', 'RENEWAL', 'NON_RENEWING_PURCHASE', 'REFUND_REVERSED')
       and (c.months is null or at_ <= ref.attributed_at + make_interval(months => c.months)) then
      r := c.rate;
      com := round(net * r, 4);
    elsif price < 0 then
      -- a refund takes back exactly what that payment earned (same rate), and nothing if it earned nothing
      select * into prior from public.purchase_events e
        where e.creator_id = c.id and e.commission_usd > 0
          and e.transaction_id is not null and e.transaction_id = p->>'transaction_id'
        order by e.event_at desc limit 1;
      if prior.event_id is not null then
        r := prior.rate;
        com := greatest(round(net * r, 4), -prior.commission_usd);
      end if;
    end if;
  end if;

  select x::uuid into who from unnest(v_ids) x
    where x ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' limit 1;
  if who is not null and ref.app_user_id is not null and ref.user_id is null then
    -- the anonymous buyer signed in later: remember the account, so claim_creator sees them as already tied
    update public.creator_referrals set user_id = who where app_user_id = ref.app_user_id
      and not exists (select 1 from public.creator_referrals o where o.user_id = who);
  end if;

  insert into public.purchase_events (event_id, type, environment, app_user_id, ids, product_id, store, period_type,
      transaction_id, original_transaction_id, currency, price_usd, net_usd, creator_id, rate, commission_usd, event_at)
    values (eid, typ, env, p->>'app_user_id', v_ids, p->>'product_id', p->>'store', p->>'period_type',
      p->>'transaction_id', p->>'original_transaction_id', p->>'currency', price, net, c.id, r, com, at_)
    on conflict (event_id) do nothing;
  return case when com <> 0 then 'commission' else 'recorded' end;
end $$;
revoke all on function public.record_purchase_event(jsonb) from public, anon, authenticated;
grant execute on function public.record_purchase_event(jsonb) to service_role;

-- ---------------------------------------------------------------------------------------------------------------
-- numbers: for you (creator_balances, SQL editor only) and for the creator (creator_stats, their private link)
-- ---------------------------------------------------------------------------------------------------------------

-- `payable` = earned more than 30 days ago (past the usual refund window) minus what was already paid out.
create or replace view public.creator_balances with (security_invoker = true) as
select c.id, c.code, c.name, c.email, c.rate, c.months, c.active,
  (select count(*) from public.creator_referrals r where r.creator_id = c.id) as signups,
  (select count(*) from public.creator_referrals r where r.creator_id = c.id and exists (select 1 from public.purchase_events e where e.creator_id = c.id and e.commission_usd > 0 and e.ids @> array[r.app_user_id])) as customers,
  coalesce((select sum(e.net_usd) from public.purchase_events e where e.creator_id = c.id and e.commission_usd <> 0), 0)::numeric(12,2) as net_sales_usd,
  coalesce((select sum(e.commission_usd) from public.purchase_events e where e.creator_id = c.id), 0)::numeric(12,2) as earned_usd,
  coalesce((select sum(p.amount_usd) from public.creator_payouts p where p.creator_id = c.id), 0)::numeric(12,2) as paid_usd,
  greatest(0,
    coalesce((select sum(e.commission_usd) from public.purchase_events e
              where e.creator_id = c.id and (e.commission_usd < 0 or e.event_at < now() - interval '30 days')), 0)
    - coalesce((select sum(p.amount_usd) from public.creator_payouts p where p.creator_id = c.id), 0))::numeric(12,2) as payable_usd
from public.creators c;
revoke all on public.creator_balances from anon, authenticated;

-- the creator's own numbers, opened with the secret key in their stats link. No customer details, totals only.
create or replace function public.creator_stats(p_code text, p_key uuid) returns jsonb
  language plpgsql stable security definer set search_path = '' as $$
declare c public.creators; res jsonb;
begin
  select * into c from public.creators where code = trim(p_code) and dashboard_key = p_key;
  if c.id is null then return null; end if;
  select jsonb_build_object(
    'name', c.name, 'code', c.code, 'rate', c.rate, 'months', c.months, 'active', c.active,
    'link', 'https://soccermax.app/join/' || c.code,
    'signups', (select count(*) from public.creator_referrals r where r.creator_id = c.id),
    'customers', (select count(*) from public.creator_referrals r where r.creator_id = c.id and exists (select 1 from public.purchase_events e where e.creator_id = c.id and e.commission_usd > 0 and e.ids @> array[r.app_user_id])),
    'earned_usd', coalesce((select sum(e.commission_usd) from public.purchase_events e where e.creator_id = c.id), 0)::numeric(12,2),
    'paid_usd', coalesce((select sum(p.amount_usd) from public.creator_payouts p where p.creator_id = c.id), 0)::numeric(12,2),
    'last_30_days_usd', coalesce((select sum(e.commission_usd) from public.purchase_events e
                                  where e.creator_id = c.id and e.event_at >= now() - interval '30 days'), 0)::numeric(12,2),
    'months_chart', coalesce((select jsonb_agg(jsonb_build_object('month', m, 'usd', usd) order by m) from (
        select to_char(date_trunc('month', e.event_at), 'YYYY-MM') as m, sum(e.commission_usd)::numeric(12,2) as usd
        from public.purchase_events e
        where e.creator_id = c.id and e.event_at >= date_trunc('month', now()) - interval '5 months'
        group by 1) t), '[]'::jsonb)
  ) into res;
  return res;
end $$;
revoke all on function public.creator_stats(text, uuid) from public;
grant execute on function public.creator_stats(text, uuid) to anon, authenticated;

-- ====================================================================================================
-- FILE: 2026-11-14-coach.sql
-- ====================================================================================================

-- AI COACH, daily allowance (2026-11-14, functions/coach). Each Coach message takes one from today's allowance.
-- The count lives in the private schema, which the app can't read or write; the only way in is coach_take(),
-- and it only ever counts the caller's own messages. Safe to re-run.

create table if not exists private.coach_usage (
  user_id uuid not null references auth.users (id) on delete cascade,
  day date not null,
  used integer not null default 0,
  primary key (user_id, day)
);
alter table private.coach_usage enable row level security;
revoke all on private.coach_usage from public, anon, authenticated;

-- Takes one message from today's allowance. Returns how many are left after this one, or -1 when there were none
-- left (nothing is taken then). "Today" is UTC.
create or replace function public.coach_take(p_limit integer)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_used integer;
begin
  if v_uid is null then raise exception 'sign in first'; end if;
  if p_limit is null or p_limit < 1 or p_limit > 200 then raise exception 'bad limit'; end if;

  insert into private.coach_usage as u (user_id, day, used)
  values (v_uid, (now() at time zone 'utc')::date, 1)
  on conflict (user_id, day) do update set used = u.used + 1
    where u.used < p_limit
  returning u.used into v_used;

  if v_used is null then return -1; end if;   -- already at the limit: the update did nothing
  return p_limit - v_used;
end $$;

revoke all on function public.coach_take(integer) from public, anon;
grant execute on function public.coach_take(integer) to authenticated;

-- old days are of no use: keep two weeks
delete from private.coach_usage where day < (now() at time zone 'utc')::date - 14;

-- ====================================================================================================
-- FILE: 2026-11-14-creator-links.sql
-- ====================================================================================================

-- CREATOR LINKS ON THE NEW WEBSITE (2026-11-14). new_creator() used to hand out soccermax.app links (the old app's
-- site, which we don't own). It now returns links on Soccer Lab's own site. Default rate 20% for 12 months, as in the
-- current proposal; pass other values to change them per creator. Safe to re-run.

create or replace function public.new_creator(p_name text, p_email text default null, p_rate numeric default 0.20, p_months integer default 12)
  returns table (creator_id uuid, creator_code text, share_link text, stats_link text)
  language plpgsql security definer set search_path = '' as $$
declare
  c public.creators;
  site constant text := 'https://glittery-banoffee-bbbd05.netlify.app';   -- change here when the site gets its own name
begin
  insert into public.creators (code, name, email, rate, months)
    values (private.new_code(), trim(p_name), nullif(trim(p_email), ''), p_rate, p_months)
    returning * into c;
  return query select c.id, c.code,
    site || '/join/' || c.code,
    site || '/creator#' || c.code || '.' || c.dashboard_key::text;
end $$;
revoke all on function public.new_creator(text, text, numeric, integer) from public, anon, authenticated;
grant execute on function public.new_creator(text, text, numeric, integer) to service_role;

-- ====================================================================================================
-- FILE: 2026-11-15-ai-and-ranks.sql
-- ====================================================================================================

-- AI FILM REVIEW + FOOD SCAN allowances, and the GLOBAL LEADERBOARD (2026-11-15; functions/film-review,
-- functions/food-scan). Safe to re-run.
--
-- 1. Daily allowances: each AI film review or food photo scan takes one from today's allowance for that kind.
--    Like coach_usage, the counts live in the private schema; the only ways in are ai_take() / ai_give_back(),
--    and they only touch the caller's own counts. The limit itself is decided by the edge function (trial / paid).
-- 2. Leaderboard: every signed-in player's XP total, written only through xp_sync() (which caps how fast it can
--    rise), read through leaderboard(). Shown names are first name + last initial, and a player can hide.

create schema if not exists private;

-- ---------------------------------------------------------------------------------------------------------------
-- 1. AI allowances
-- ---------------------------------------------------------------------------------------------------------------
create table if not exists private.ai_usage (
  user_id uuid not null references auth.users (id) on delete cascade,
  day date not null,
  kind text not null check (kind in ('film', 'food')),
  used integer not null default 0,
  primary key (user_id, day, kind)
);
alter table private.ai_usage enable row level security;
revoke all on private.ai_usage from public, anon, authenticated;

-- Takes one from today's allowance of p_kind. Returns how many are left after this one, or -1 when there were none
-- left (nothing is taken then). "Today" is UTC.
create or replace function public.ai_take(p_kind text, p_limit integer)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_used integer;
begin
  if v_uid is null then raise exception 'sign in first'; end if;
  if p_kind not in ('film', 'food') then raise exception 'bad kind'; end if;
  if p_limit is null or p_limit < 1 or p_limit > 100 then raise exception 'bad limit'; end if;

  insert into private.ai_usage as u (user_id, day, kind, used)
  values (v_uid, (now() at time zone 'utc')::date, p_kind, 1)
  on conflict (user_id, day, kind) do update set used = u.used + 1
    where u.used < p_limit
  returning u.used into v_used;

  if v_used is null then return -1; end if;
  return p_limit - v_used;
end $$;

-- Gives one back (the AI call failed, so it shouldn't count). Never goes below zero.
create or replace function public.ai_give_back(p_kind text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if auth.uid() is null then raise exception 'sign in first'; end if;
  update private.ai_usage set used = greatest(0, used - 1)
   where user_id = auth.uid() and day = (now() at time zone 'utc')::date and kind = p_kind;
end $$;

-- How many of p_kind the caller has used today (the app shows "3 of 5 left" before the first scan).
create or replace function public.ai_used_today(p_kind text)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((select used from private.ai_usage
                    where user_id = auth.uid() and day = (now() at time zone 'utc')::date and kind = p_kind), 0);
$$;

revoke all on function public.ai_take(text, integer) from public, anon;
revoke all on function public.ai_give_back(text) from public, anon;
revoke all on function public.ai_used_today(text) from public, anon;
grant execute on function public.ai_take(text, integer) to authenticated;
grant execute on function public.ai_give_back(text) to authenticated;
grant execute on function public.ai_used_today(text) to authenticated;

delete from private.ai_usage where day < (now() at time zone 'utc')::date - 14;

-- ---------------------------------------------------------------------------------------------------------------
-- 2. Global leaderboard
-- ---------------------------------------------------------------------------------------------------------------
create table if not exists private.player_xp (
  user_id uuid primary key references auth.users (id) on delete cascade,
  name text not null default 'Player',
  position text,
  xp integer not null default 0 check (xp >= 0),
  hidden boolean not null default false,
  -- anti-cheat: XP can only rise so much per UTC day
  day date not null default (now() at time zone 'utc')::date,
  day_start_xp integer not null default 0,
  updated_at timestamptz not null default now()
);
alter table private.player_xp enable row level security;
revoke all on private.player_xp from public, anon, authenticated;
create index if not exists player_xp_xp on private.player_xp (xp desc);

-- How much XP one day may add. A huge training day earns about 1,000; this leaves room and stops edited numbers.
create or replace function private.xp_day_cap() returns integer language sql immutable as $$ select 2500 $$;

-- "Muhammad Ali" -> "Muhammad A." ; empty -> "Player". Letters, digits, spaces, dots, hyphens and apostrophes only.
create or replace function private.short_name(p text)
returns text
language sql
immutable
as $$
  with c as (select trim(regexp_replace(coalesce(p, ''), '[^[:alnum:] .''-]', '', 'g')) as s),
       w as (select regexp_split_to_array(s, '\s+') as a from c)
  select case
    when (select s from c) = '' then 'Player'
    when array_length(a, 1) = 1 then left(a[1], 16)
    else left(a[1], 16) || ' ' || left(a[array_length(a, 1)], 1) || '.'
  end
  from w;
$$;

-- Save my XP (the app sends its own total) and return where I stand:
-- {"rank": 12, "total": 340, "xp": 4210, "hidden": false}. XP never goes down here (a reinstall that lost history
-- keeps the best total), and it can rise at most xp_day_cap() per UTC day.
create or replace function public.xp_sync(p_xp integer, p_name text, p_position text, p_hidden boolean default null)
returns json
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_today date := (now() at time zone 'utc')::date;
  r private.player_xp;
  v_new integer;
begin
  if v_uid is null then raise exception 'sign in first'; end if;
  insert into private.player_xp (user_id, name, position, xp, day, day_start_xp)
  values (v_uid, private.short_name(p_name), left(p_position, 4), 0, v_today, 0)
  on conflict (user_id) do nothing;

  select * into r from private.player_xp where user_id = v_uid for update;
  if r.day <> v_today then r.day := v_today; r.day_start_xp := r.xp; end if;
  v_new := greatest(r.xp, least(coalesce(p_xp, 0), r.day_start_xp + private.xp_day_cap()));

  update private.player_xp set
    xp = v_new,
    name = private.short_name(p_name),
    position = left(p_position, 4),
    hidden = coalesce(p_hidden, hidden),
    day = r.day,
    day_start_xp = r.day_start_xp,
    updated_at = now()
  where user_id = v_uid
  returning * into r;

  return json_build_object(
    'rank', 1 + (select count(*) from private.player_xp where xp > r.xp),
    'total', (select count(*) from private.player_xp),
    'xp', r.xp,
    'hidden', r.hidden);
end $$;

-- The top of the table (hidden players left out; the caller is always marked "me").
create or replace function public.leaderboard(p_limit integer default 50)
returns table (place bigint, name text, pos text, xp integer, me boolean)
language sql
stable
security definer
set search_path = ''
as $$
  select rank() over (order by p.xp desc) as place, p.name, p.position as pos, p.xp, p.user_id = auth.uid() as me
  from private.player_xp p
  where (not p.hidden or p.user_id = auth.uid()) and auth.uid() is not null
  order by p.xp desc, p.updated_at
  limit least(greatest(coalesce(p_limit, 50), 1), 100);
$$;

revoke all on function public.xp_sync(integer, text, text, boolean) from public, anon;
revoke all on function public.leaderboard(integer) from public, anon;
grant execute on function public.xp_sync(integer, text, text, boolean) to authenticated;
grant execute on function public.leaderboard(integer) to authenticated;

-- ====================================================================================================
-- FILE: 2026-11-13-new-project-finish.sql
-- ====================================================================================================

-- NEW PROJECT, LAST STEP (2026-11-12). Run after every other file in this folder (or as the end of
-- setup-new-project.sql). It closes the gaps the dated files leave on a project that isn't the original one.
-- Safe to re-run.

-- 1. Columns added after the base file that the app itself writes: the streak bitmap (2026-10-27-team-streak.sql).
--    free_for_life (lifetime codes) is deliberately NOT here: only redeem_lifetime() may set it.
grant insert (kept, kept_end), update (kept, kept_end) on public.profiles to authenticated;

-- 2. Team functions made without an explicit grant: signed-in players only, never signed-out visitors.
revoke all on function public.create_team(text, text, integer), public.join_team(text) from public, anon;
grant execute on function public.create_team(text, text, integer), public.join_team(text) to authenticated;

-- 3. Internal helpers: callable by the rules that use them, by nobody directly from outside.
revoke all on function private.new_code() from public, anon, authenticated;
revoke all on function private.feed_rate_limit() from public, anon, authenticated;
revoke all on function private.my_teams() from public, anon;
grant execute on function private.my_teams() to authenticated;

-- 3b. Signed-out visitors get no table at all except public match data. Row Level Security already returns them
--     nothing; this takes away the empty answer too. Tables with no rules are also closed to signed-in players.
revoke all on public.backups, public.blocks, public.gifts, public.lifetime_codes, public.reports from anon;
revoke all on public.gifts, public.lifetime_codes, public.reports from authenticated;

-- 4. Matchday's two nightly jobs were written with the FIRST project's address inside them. On a new project they
--    would call someone else's server, so they are removed here. To turn Matchday's nightly pull on for this
--    project: deploy functions/matchday-pull, set its APISPORTS_KEY secret, put this project's ref (the letters in
--    https://<ref>.supabase.co) in v_ref below, and run this file again.
do $$
declare
  v_ref text := '';      -- e.g. 'abcdefghijklmnopqrst'
  v_url text;
begin
  perform cron.unschedule(jobname) from cron.job where jobname in ('matchday-pull-europe', 'matchday-pull-americas');
  if v_ref ~ '^[a-z0-9]{15,30}$' then
    v_url := 'https://' || v_ref || '.supabase.co/functions/v1/matchday-pull';
    perform cron.schedule('matchday-pull-europe', '50 23 * * *', format(
      $job$select net.http_post(url := %L, headers := jsonb_build_object('x-cron-secret', (select secret from private.matchday_cron)), timeout_milliseconds := 140000)$job$,
      v_url || '?tz=UTC'));
    perform cron.schedule('matchday-pull-americas', '30 5 * * *', format(
      $job$select net.http_post(url := %L, headers := jsonb_build_object('x-cron-secret', (select secret from private.matchday_cron)), timeout_milliseconds := 140000)$job$,
      v_url || '?tz=America/Sao_Paulo'));
    raise notice 'Matchday nightly pull scheduled for %', v_url;
  else
    raise notice 'Matchday nightly pull is OFF (no project ref set in this file).';
  end if;
end $$;

-- 5. A last look: every table in public must have Row Level Security on. This stops the run if one doesn't.
do $$
declare bad text;
begin
  select string_agg(c.relname, ', ') into bad
  from pg_class c join pg_namespace n on n.oid = c.relnamespace
  where n.nspname = 'public' and c.relkind = 'r' and not c.relrowsecurity;
  if bad is not null then raise exception 'Row Level Security is OFF on: %', bad; end if;
end $$;

commit;
